insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-naya-applicator-kit', 'Naya Applicator Kit', 'Naya', 'tampon', 'physical', 'A reusable tampon applicator, designed to be used again instead of discarded after each insertion, so you get the comfort of an applicator without the plastic waste, per Naya. The kit comes with five tampons, so you can try the applicator across the start of a cycle, and a protective cotton pouch that keeps it clean and discreet in a bag, pocket or gym locker between uses. Naya hasn''t launched yet: the first 5,000 waitlist sign-ups get access to its first batch.', '$28.99 (listed price; pre-launch, join the waitlist)', '/products/naya/applicator-kit.webp', 'https://www.naya-applicator.com/', '["sustainability","reusable","waitlist","pre-launch","cost"]'::jsonb, '["menstrual-collection"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Pre-launch. ayna found no FDA registration or 510(k) clearance for Naya Applicator LLC or this applicator (openFDA, checked 2026-11-04). The tampons are used with the applicator; tampons are regulated by the FDA as medical devices.","materials":"One reusable tampon applicator, five tampons and a cotton storage pouch, per naya-applicator.com. Naya hasn''t published the applicator''s material yet.","recalls":"Not yet released, no recalls.","sideEffects":"Naya is still in R&D and says final care instructions are coming; for now it says to rinse the applicator with water after each use. Cleaning instructions will be included with the kit.","opinionAlerts":"Pre-launch: final design, care instructions and ship date aren''t set yet."}'::jsonb, 'Naya says it is building the first self-cleaning reusable tampon applicator in the U.S. The product hasn''t launched, so there is no published testing of its cleaning, safety or fit yet. Founder Julia started Naya after living in Berlin for four months, where she couldn''t find a tampon she could use, and wanted a safe, reusable alternative to single-use plastic applicators.', 'Naya hasn''t launched, so there are no customer reviews yet.', 'Not yet released; no study of the applicator has been published.', 'brand', 'Sourced from Naya''s own site (naya-applicator.com), not independent clinical literature.', 'curated', true, false, null, true, '{"prelaunch":true,"waitlistCtaLabel":"Join the waitlist","affiliateUrl":"https://www.naya-applicator.com/waitlist?SQF_REFERRAL_SOURCE=ayna","gallery":["/products/naya/applicator-kit-contents.webp","/products/naya/applicator-kit-pouch.webp"],"doctorOpinionShort":"A reusable tampon applicator to cut plastic waste, per Naya. Pre-launch, so there is no published testing of it yet.","whoItsFor":["People who prefer applicator tampons and want to cut single-use plastic waste (per Naya)","Early adopters comfortable joining a waitlist before the product ships"],"howToUse":{"intro":"Per Naya''s site:","steps":["Remove the packaging from an applicator-free tampon and pull out the string.","Insert the tampon into the applicator.","Use it as you would a normal applicator tampon.","Clean the applicator with water after use. Naya says final care instructions will come with the kit."],"sourceUrl":"https://www.naya-applicator.com/","sourceLabel":"naya-applicator.com: How it works"},"warnings":["Pre-launch: specs, final care instructions and ship date are not final.","Naya ships only to the US once launched, per its FAQ."],"ingredients":"Reusable tampon applicator; five tampons; cotton storage pouch.","scientificCitations":[],"integrations":[],"badges":["Pre-launch","Waitlist","Female-Founded"],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://www.naya-applicator.com/ourstory","text":"naya-applicator.com: Our Story","summary":"Founder Julia on why she started Naya."},{"platform":"website","url":"https://www.naya-applicator.com/faq-1","text":"naya-applicator.com: FAQ","summary":"Sizing, care (still in R&D) and shipping (US only once launched)."}]}},"isEmergingBrand":true}'::jsonb),
  ('p-naya-regular-tampons', 'Naya Regular Tampons', 'Naya', 'tampon', 'physical', 'Regular, applicator-free tampons (32), 100% plastic-free and cellophane wrapped, per Naya. Made for use with the Naya reusable applicator, or without it. Not yet released: join Naya''s waitlist to be first to know when they''re on the market.', '$12.00 for 32 (listed price; pre-launch, join the waitlist)', '/products/naya/regular-tampons.webp', 'https://www.naya-applicator.com/shop/p/regular-tampons', '["sustainability","waitlist","pre-launch"]'::jsonb, '["menstrual-collection"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Tampons are regulated by the FDA as medical devices. ayna found no FDA registration or 510(k) clearance for Naya Applicator LLC (openFDA, checked 2026-11-04); naya-applicator.com doesn''t list who makes the tampons.","materials":"32 regular-absorbency, applicator-free tampons, cellophane wrapped, 100% plastic-free, per Naya.","recalls":"Not yet released, no recalls.","opinionAlerts":"Pre-launch: Naya hasn''t published the tampons'' materials or manufacturer yet."}'::jsonb, 'Naya recommends starting with its Regular applicator kit and Regular tampons; its applicators fit tampons by industry-standard absorbency levels. The tampons haven''t launched, and Naya hasn''t published their materials or maker yet.', 'Not yet released, so there are no customer reviews yet.', 'Not yet released.', 'brand', 'Sourced from Naya''s own site (naya-applicator.com), not independent clinical literature.', 'curated', true, false, null, true, '{"prelaunch":true,"waitlistCtaLabel":"Join the waitlist","affiliateUrl":"https://www.naya-applicator.com/waitlist?SQF_REFERRAL_SOURCE=ayna","doctorOpinionShort":"Applicator-free, plastic-free regular tampons made to pair with Naya''s reusable applicator. Pre-launch.","whoItsFor":["People using the Naya reusable applicator, or anyone who wants plastic-free, applicator-free tampons (per Naya)"],"warnings":["Pre-launch: materials and ship date aren''t final."],"ingredients":"32 regular, applicator-free tampons (materials not yet published).","scientificCitations":[],"integrations":[],"badges":["Pre-launch","Waitlist"],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://www.naya-applicator.com/faq-1","text":"naya-applicator.com: FAQ","summary":"Sizing and shipping (US only once launched)."}]}},"isEmergingBrand":true}'::jsonb)
